import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Filter, 
  ExternalLink, 
  Star, 
  Clock, 
  BookOpen, 
  Zap,
  Search,
  Grid,
  List,
  TrendingUp
} from 'lucide-react';
import { useUser } from '../context/UserContext';
import { 
  learningResources, 
  getAllResources, 
  filterResourcesByType, 
  getRecommendedResources 
} from '../data/resources';
import './SmartRecommendations.css';

const SmartRecommendations = () => {
  const { user } = useUser();
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [selectedType, setSelectedType] = useState('All');
  const [searchQuery, setSearchQuery] = useState('');
  const [viewMode, setViewMode] = useState('grid'); // 'grid' or 'list'
  const [showRecommended, setShowRecommended] = useState(true);

  const categories = ['All', ...Object.keys(learningResources)];
  const types = ['All', 'Free', 'Paid'];

  // Get user interests from onboarding data
  const userInterests = useMemo(() => {
    if (!user?.careerGoals && !user?.techStack) return [];

    const interests = [];

    // Map career goals to categories
    const careerGoalMapping = {
      'ml-engineer': 'AI & Machine Learning',
      'data-scientist': 'Data Science',
      'fullstack': 'Full Stack Development',
      'devops': 'DevOps',
      'frontend': 'Full Stack Development',
      'backend': 'Full Stack Development'
    };

    // Map tech stack to categories
    const techStackMapping = {
      'ml': 'AI & Machine Learning',
      'python': 'Data Science',
      'react': 'Full Stack Development',
      'nodejs': 'Full Stack Development',
      'javascript': 'Full Stack Development'
    };

    user?.careerGoals?.forEach(goal => {
      if (careerGoalMapping[goal]) {
        interests.push(careerGoalMapping[goal]);
      }
    });

    user?.techStack?.forEach(tech => {
      if (techStackMapping[tech]) {
        interests.push(techStackMapping[tech]);
      }
    });

    return [...new Set(interests)]; // Remove duplicates
  }, [user]);

  // Filter and search resources
  const filteredResources = useMemo(() => {
    let resources = [];

    if (showRecommended && userInterests.length > 0) {
      resources = getRecommendedResources(userInterests);
    } else if (selectedCategory === 'All') {
      resources = getAllResources();
    } else {
      resources = learningResources[selectedCategory] || [];
    }

    // Filter by type
    resources = filterResourcesByType(resources, selectedType);

    // Filter by search query
    if (searchQuery) {
      resources = resources.filter(resource =>
        resource.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        resource.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
        resource.provider.toLowerCase().includes(searchQuery.toLowerCase())
      );
    }

    return resources;
  }, [selectedCategory, selectedType, searchQuery, showRecommended, userInterests]);

  const handleResourceClick = (resource) => {
    // Track resource click for analytics
    console.log('Resource clicked:', resource.name);
    window.open(resource.link, '_blank', 'noopener,noreferrer');
  };

  const getTypeColor = (type) => {
    return type === 'Free' ? 'type-free' : 'type-paid';
  };

  const getLevelColor = (level) => {
    const colors = {
      'Beginner': 'level-beginner',
      'Intermediate': 'level-intermediate',
      'Advanced': 'level-advanced',
      'All levels': 'level-all'
    };
    return colors[level] || 'level-default';
  };

  return (
    <motion.div 
      className="smart-recommendations"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5 }}
    >
      <div className="container mx-auto px-4 py-8">
        {/* Header */}
        <div className="recommendations-header mb-8">
          <div className="flex items-center gap-3 mb-4">
            <BookOpen className="text-blue-600" size={32} />
            <h1 className="text-3xl font-bold text-gray-800">Smart Learning Recommendations</h1>
          </div>
          <p className="text-gray-600 text-lg">
            Discover curated learning resources tailored to your career goals and interests
          </p>

          {userInterests.length > 0 && (
            <div className="mt-4 p-4 bg-blue-50 rounded-lg border border-blue-200">
              <div className="flex items-center gap-2 mb-2">
                <TrendingUp className="text-blue-600" size={20} />
                <span className="font-semibold text-blue-800">Personalized for you:</span>
              </div>
              <div className="flex flex-wrap gap-2">
                {userInterests.map((interest, index) => (
                  <span 
                    key={index}
                    className="px-3 py-1 bg-blue-100 text-blue-700 rounded-full text-sm font-medium"
                  >
                    {interest}
                  </span>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Filters and Controls */}
        <div className="filters-section mb-8 p-6 bg-white rounded-xl shadow-sm border border-gray-200">
          <div className="flex flex-wrap items-center gap-4 mb-4">
            {/* Search */}
            <div className="relative flex-1 min-w-64">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={20} />
              <input
                type="text"
                placeholder="Search resources..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              />
            </div>

            {/* View Mode Toggle */}
            <div className="flex bg-gray-100 rounded-lg p-1">
              <button
                onClick={() => setViewMode('grid')}
                className={`p-2 rounded-md transition-colors ${
                  viewMode === 'grid' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-600'
                }`}
              >
                <Grid size={20} />
              </button>
              <button
                onClick={() => setViewMode('list')}
                className={`p-2 rounded-md transition-colors ${
                  viewMode === 'list' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-600'
                }`}
              >
                <List size={20} />
              </button>
            </div>
          </div>

          <div className="flex flex-wrap items-center gap-4">
            {/* Recommended Toggle */}
            {userInterests.length > 0 && (
              <label className="flex items-center gap-2 cursor-pointer">
                <input
                  type="checkbox"
                  checked={showRecommended}
                  onChange={(e) => setShowRecommended(e.target.checked)}
                  className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                />
                <span className="text-sm font-medium text-gray-700">Show Recommended First</span>
              </label>
            )}

            {/* Category Filter */}
            <div className="flex items-center gap-2">
              <Filter className="text-gray-500" size={16} />
              <select
                value={selectedCategory}
                onChange={(e) => setSelectedCategory(e.target.value)}
                className="border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              >
                {categories.map(category => (
                  <option key={category} value={category}>{category}</option>
                ))}
              </select>
            </div>

            {/* Type Filter */}
            <div className="flex bg-gray-100 rounded-lg p-1">
              {types.map(type => (
                <button
                  key={type}
                  onClick={() => setSelectedType(type)}
                  className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${
                    selectedType === type 
                      ? 'bg-white shadow-sm text-blue-600' 
                      : 'text-gray-600 hover:text-gray-800'
                  }`}
                >
                  {type}
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Results Count */}
        <div className="mb-6">
          <p className="text-gray-600">
            Showing <span className="font-semibold text-gray-800">{filteredResources.length}</span> resources
            {selectedCategory !== 'All' && (
              <span> in <span className="font-semibold text-blue-600">{selectedCategory}</span></span>
            )}
          </p>
        </div>

        {/* Resources Grid/List */}
        <AnimatePresence mode="wait">
          {filteredResources.length === 0 ? (
            <motion.div 
              className="text-center py-12"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
            >
              <BookOpen className="mx-auto text-gray-400 mb-4" size={64} />
              <h3 className="text-xl font-semibold text-gray-600 mb-2">No resources found</h3>
              <p className="text-gray-500">Try adjusting your filters or search terms</p>
            </motion.div>
          ) : (
            <motion.div 
              className={`resources-container ${viewMode === 'grid' ? 'resources-grid' : 'resources-list'}`}
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
            >
              {filteredResources.map((resource, index) => (
                <motion.div
                  key={resource.id}
                  className={`resource-card ${viewMode === 'list' ? 'resource-card-list' : ''}`}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: index * 0.05 }}
                  whileHover={{ y: -4 }}
                >
                  <div className="resource-header">
                    <div className="flex items-start justify-between gap-3">
                      <h3 className="resource-title">{resource.name}</h3>
                      <div className="flex flex-col gap-2">
                        <span className={`type-badge ${getTypeColor(resource.type)}`}>
                          {resource.type}
                        </span>
                        {resource.level && (
                          <span className={`level-badge ${getLevelColor(resource.level)}`}>
                            {resource.level}
                          </span>
                        )}
                      </div>
                    </div>
                    <p className="provider-name">{resource.provider}</p>
                  </div>

                  <p className="resource-description">{resource.description}</p>

                  <div className="resource-meta">
                    <div className="flex items-center gap-4 text-sm text-gray-600">
                      {resource.rating && (
                        <div className="flex items-center gap-1">
                          <Star className="text-yellow-500" size={16} fill="currentColor" />
                          <span>{resource.rating}</span>
                        </div>
                      )}
                      {resource.duration && (
                        <div className="flex items-center gap-1">
                          <Clock className="text-gray-500" size={16} />
                          <span>{resource.duration}</span>
                        </div>
                      )}
                    </div>
                  </div>

                  <button
                    onClick={() => handleResourceClick(resource)}
                    className="resource-button"
                  >
                    <span>Go to Resource</span>
                    <ExternalLink size={16} />
                  </button>
                </motion.div>
              ))}
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </motion.div>
  );
};

export default SmartRecommendations;
